/* Load project.json before legacy controllers. No silent HTTP fallback to stale defaults.
 * Local file mode uses only the snapshot generated by rebuild_project.cjs.
 * Preserve source script ordering; inline completion calls are named actions, not eval.
 */
(async()=>{'use strict';const fail=error=>{window.workspaceBootFailures.push('project.json / inicializace: '+error.message);window.workspaceBootFinish(false);const e=document.getElementById('workspaceBootStatus');if(e)e.textContent='Konfiguraci nebo součást aplikace se nepodařilo načíst';console.error(error);};
try{
let config,source;
if(location.protocol==='file:'){config=JSON.parse(document.getElementById('projectConfigSnapshot').textContent);source='generated-file-snapshot';}
else{const response=await fetch(new URL('project.json',document.baseURI),{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw Error('project.json: HTTP '+response.status);config=await response.json();source='project.json';}
await ProjectConfig.init(config,source);ProjectConfig.apply();
const scriptErrors=[];const capture=e=>{if(e.message)scriptErrors.push(e.message);};window.addEventListener('error',capture);
for(const item of document.querySelectorAll('script[type="application/x-dashboard-script"],script[type="application/x-dashboard-action"]')){
if(item.dataset.action==='finish-ui'){DashboardUI.finish();DashboardMapRefinements.init();continue;}
const src=item.dataset.src;if(!src||src.startsWith('/')||/^[a-z]+:/i.test(src)||src.split('/').includes('..'))throw Error('Nepovolená cesta řídicího souboru.');
await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.async=false;script.onload=resolve;script.onerror=()=>reject(Error('Chybí součást '+src));item.after(script);});
if(scriptErrors.length)throw Error(scriptErrors.join('\n'));
}
window.removeEventListener('error',capture);ProjectConfig.checkReferences(DOCS);ProjectConfig.apply();
const dialog=document.getElementById('dashboardFilesDialog');if(dialog){const p=document.createElement('p');p.className='project-config-status';p.textContent=source==='project.json'?'Projektové údaje, ceny a harmonogram: project.json, načteno přímo při otevření.':'Otevřeno jako místní soubor: používá se generovaná kopie project.json. Po ruční změně spusťte node rebuild_project.cjs nebo otevřete dashboard přes místní HTTP server.';dialog.append(p);}
window.workspaceBootFinish(!!(window.SharedWorkspaceUI&&window.OfferCalculator&&window.DocumentWorkspaceUI&&window.SceneBalanceQA));
}catch(e){fail(e);}})();
